BEGIN;
create temp table assertion_count(n int);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create function pg_temp.throws(statement text,label text)returns void language plpgsql as $$declare failed boolean:=false;begin begin execute statement;exception when others then failed:=true;end;perform pg_temp.check_it(failed,label);end$$;
create temp table st(k text primary key,v jsonb);
insert into public.properties(id,org_id,name)values('ee600000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','Neighborhood review SQL fixture'),('ee600000-0000-4000-8000-000000000002','22222222-2222-2222-2222-222222222222','Other neighborhood review SQL fixture');
create function pg_temp.read_source(b jsonb default'{}',p uuid default'ee600000-0000-4000-8000-000000000001')returns jsonb language sql as $$select public.read_neighborhood_reviews(p,'11111111-1111-1111-1111-111111111111',b)$$;
create function pg_temp.decide(i uuid,b jsonb,p uuid default'ee600000-0000-4000-8000-000000000001')returns jsonb language sql as $$select public.decide_neighborhood_review(i,p,'11111111-1111-1111-1111-111111111111',b)$$;
create function pg_temp.draft()returns jsonb language sql as $$select'{"name":"Station garden","category":"park","address":{"street":"1 Fixture Lane","extra":{"retained":"original value"}},"latitude":0,"longitude":0,"distanceMiles":0,"travelTimeMinutes":null,"sourceUrl":"https://example.invalid/park","capturedAt":"2026-01-01T12:34:56.789+02:00","confidence":0}'::jsonb$$;
create function pg_temp.save_input(i uuid default null,b jsonb default null)returns jsonb language sql as $$select jsonb_build_object('operation','save','pointId',i,'expectedStateHash',public.knowledge_hash(public.neighborhood_point_state(i)),'draft',coalesce(b,pg_temp.draft()),'reason','Retain exact supplied neighborhood source')$$;
create function pg_temp.review_input(i uuid,op text default'approve')returns jsonb language sql as $$select jsonb_build_object('operation',op,'pointId',i,'expectedStateHash',public.knowledge_hash(public.neighborhood_point_state(i)),'confirmed',true,'reason','Review exact retained neighborhood source')||case when op in('approve','reject')then jsonb_build_object('versionId',(public.neighborhood_point_state(i))->'latestVersion'->>'id')else'{}'end$$;
select pg_temp.check_it(pg_temp.read_source()->>'total'='0','empty source inventory');
insert into st values('save',pg_temp.save_input());
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000010',(select v from st where k='save'))->>'state'='saved','new private source draft');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000010',(select v from st where k='save'))->>'state'='replayed','lost draft reply replays original');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000010',(select v||'{"reason":"Different request"}'from st where k='save'))->>'state'='request_conflict','same identity different input held');
select pg_temp.check_it(not exists(select 1 from public.property_points_of_interest where id='ee600000-0000-4000-8000-000000000010'),'draft creates no marketing facts');
select pg_temp.check_it((select draft=pg_temp.draft()from public.neighborhood_versions where id='ee600000-0000-4000-8000-000000000010'),'exact source time address metadata zeros retained');
insert into st values('approve',pg_temp.review_input('ee600000-0000-4000-8000-000000000010'));
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000011',(select v from st where k='approve'))->>'state'='saved','exact source approval');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000011',(select v from st where k='approve'))->>'state'='replayed','lost approval reply replays');
select pg_temp.check_it((select approval_status='approved'and approved_by='11111111-1111-1111-1111-111111111111'and approved_at is not null and distance_miles=0 and travel_time_minutes is null and confidence=0 and latitude=0 and longitude=0 and address=pg_temp.draft()->'address'and captured_at='2026-01-01T10:34:56.789Z'from public.property_points_of_interest where id='ee600000-0000-4000-8000-000000000010'),'actual actor approval and lossless typed facts');
insert into public.shared_context_snapshots(id,org_id,property_id,source_domain,context_hash,context_payload)values('ee600000-0000-4000-8000-000000000085','22222222-2222-2222-2222-222222222222','ee600000-0000-4000-8000-000000000001','forgestudio.generation','fixture-neighborhood-source',jsonb_build_object('version','forgestudio.context.v1','propertyId','ee600000-0000-4000-8000-000000000001','contextHash','fixture-neighborhood-source','sourceRecords',jsonb_build_object('poi:ee600000-0000-4000-8000-000000000010',jsonb_build_object('kind','poi','id','ee600000-0000-4000-8000-000000000010','values',public.read_forgestudio_source_record('ee600000-0000-4000-8000-000000000001','poi','ee600000-0000-4000-8000-000000000010'))),'sources',jsonb_build_array(jsonb_build_object('id','approved_poi:ee600000-0000-4000-8000-000000000010','kind','approved_poi','recordKey','poi:ee600000-0000-4000-8000-000000000010','label','Supplied fixture place','content','Station garden','allowedUses','["claim"]'::jsonb))));
insert into st values('claim','{"claims":[{"type":"neighborhood","text":"Station garden","citations":[{"sourceId":"approved_poi:ee600000-0000-4000-8000-000000000010","sourceType":"approved_poi"}]}]}'::jsonb);
select pg_temp.check_it(public.check_forgestudio_sources('ee600000-0000-4000-8000-000000000001','ee600000-0000-4000-8000-000000000085',(select v from st where k='claim'))->>'state'='current','ForgeStudio current supplied source qualifies');
insert into st values('approvedRows',public.neighborhood_approved_rows('ee600000-0000-4000-8000-000000000001'));
select pg_temp.check_it(public.neighborhood_snapshot_matches_current('ee600000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222',(select v from st where k='approvedRows')),'current readiness basis qualifies');
insert into public.property_onboarding_snapshots(id,property_id,org_id,status,content_hash,snapshot_payload)values('ee600000-0000-4000-8000-000000000080','ee600000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','approved',repeat('a',64),jsonb_build_object('pointsOfInterest',(select v from st where k='approvedRows')));
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000012',pg_temp.save_input('ee600000-0000-4000-8000-000000000010',pg_temp.draft()||'{"name":"Corrected garden","distanceMiles":2.5}'))->>'state'='saved','correction saved privately');
select pg_temp.check_it((select name='Station garden'and approval_status='approved'from public.property_points_of_interest where id='ee600000-0000-4000-8000-000000000010')and(select status='approved'from public.property_onboarding_snapshots where id='ee600000-0000-4000-8000-000000000080'),'private edits preserve approval and readiness');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000013',(select v from st where k='approve'))->>'state'='source_changed','stale review fenced');
insert into st values('correction',pg_temp.review_input('ee600000-0000-4000-8000-000000000010'));
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000014',(select v from st where k='correction'))->>'staleReadinessCount'='1','replacement invalidates exact readiness');
select pg_temp.check_it((select status='stale'from public.property_onboarding_snapshots where id='ee600000-0000-4000-8000-000000000080')and(select name='Corrected garden'from public.property_points_of_interest where id='ee600000-0000-4000-8000-000000000010'),'replacement effective atomically');
select pg_temp.check_it((select after_state->'invalidatedReadiness'->0->>'id'='ee600000-0000-4000-8000-000000000080'and after_state->'latestReview'->>'id'=id::text from public.neighborhood_decisions where id='ee600000-0000-4000-8000-000000000014'),'exact stale IDs and resulting review retained');
select pg_temp.check_it(public.check_forgestudio_sources('ee600000-0000-4000-8000-000000000001','ee600000-0000-4000-8000-000000000085',(select v from st where k='claim'))->>'state'='source_review_required','ForgeStudio rejects replaced source claims');
select pg_temp.check_it(public.read_neighborhood_publication_source('ee600000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222',(select v from st where k='approvedRows'))->>'state'='source_changed','generation rejects old snapshot');
select pg_temp.throws($q$update public.property_onboarding_snapshots set status='approved'where id='ee600000-0000-4000-8000-000000000080'$q$,'late obsolete readiness approval blocked');
insert into public.property_onboarding_snapshots(id,property_id,org_id,status,content_hash,snapshot_payload)values('ee600000-0000-4000-8000-000000000081','ee600000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','ready',repeat('b',64),jsonb_build_object('pointsOfInterest',(select v from st where k='approvedRows')));
select pg_temp.check_it((select status='stale'from public.property_onboarding_snapshots where id='ee600000-0000-4000-8000-000000000081'),'late obsolete build becomes stale');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000015',pg_temp.review_input('ee600000-0000-4000-8000-000000000010','withdraw'))->>'state'='saved','withdrawal recorded');
select pg_temp.check_it(jsonb_array_length(public.neighborhood_approved_rows('ee600000-0000-4000-8000-000000000001'))=0,'withdrawn facts unavailable');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000016',pg_temp.review_input('ee600000-0000-4000-8000-000000000010','archive'))->>'state'='saved','archive retained');
select pg_temp.check_it(pg_temp.read_source()->'items'->0->>'archived'='true','archived item remains in complete inventory');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000017',pg_temp.save_input('ee600000-0000-4000-8000-000000000010'))->>'state'='archived','archived editing held');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000018',pg_temp.review_input('ee600000-0000-4000-8000-000000000010','restore'))->>'state'='saved','restore recorded');
select pg_temp.check_it(jsonb_array_length(public.neighborhood_approved_rows('ee600000-0000-4000-8000-000000000001'))=0,'restore never silently approves');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000019',pg_temp.save_input('ee600000-0000-4000-8000-000000000010',pg_temp.draft()||'{"sourceUrl":"","capturedAt":null,"confidence":null}'))->>'state'='saved','incomplete drafts retained');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000020',pg_temp.review_input('ee600000-0000-4000-8000-000000000010'))->>'state'='review_incomplete','incomplete approval blocked');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000021',pg_temp.review_input('ee600000-0000-4000-8000-000000000010','reject'))->>'state'='saved','rejected draft retained');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000022',pg_temp.review_input('ee600000-0000-4000-8000-000000000010'))->>'state'='version_not_current','rejected version cannot be approved');
select pg_temp.check_it(not public.valid_neighborhood_draft(pg_temp.draft()||'{"latitude":0.1234567}')and not public.valid_neighborhood_draft(pg_temp.draft()||'{"distanceMiles":1.234}')and not public.valid_neighborhood_draft(pg_temp.draft()||'{"travelTimeMinutes":0.5}'),'unsupported numeric precision held without rounding');
select pg_temp.check_it(not public.valid_neighborhood_draft(pg_temp.draft()||'{"longitude":null}')and not public.valid_neighborhood_draft(pg_temp.draft()||'{"sourceUrl":"https://user:pass@example.invalid"}'),'coordinate pairs and credential-free sources required');
select pg_temp.check_it(not public.valid_neighborhood_draft(pg_temp.draft()||'{"capturedAt":"2099-01-01T00:00:00Z"}',true)and not public.valid_neighborhood_draft(pg_temp.draft()||'{"capturedAt":"2026-01-01T00:00:00"}'),'future or zoneless reported source time cannot approve');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000023',jsonb_build_object('operation','cancel_unused','inputHash',repeat('c',64),'reason','Stop unused request'))->>'state'='cancelled','cancel unused persisted');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000023',pg_temp.save_input())->>'state'='decision_cancelled','cancel fences delayed save');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000011',jsonb_build_object('operation','cancel_unused','inputHash',repeat('d',64),'reason','Check possibly saved request'))->>'state'='replayed','cancel cannot undo approval');
select pg_temp.check_it(pg_temp.read_source('{"kind":"decision","decisionId":"ee600000-0000-4000-8000-000000000014"}')->>'pointId'='ee600000-0000-4000-8000-000000000010','saved decision recovery');
select pg_temp.check_it(pg_temp.read_source('{"kind":"history_detail","decisionId":"ee600000-0000-4000-8000-000000000014"}')->'decision'->'before_state'->'point'->>'name'='Station garden','private before state preserved');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000024',pg_temp.save_input('ee600000-0000-4000-8000-000000000010'),'ee600000-0000-4000-8000-000000000002')->>'state'='not_found','cross-property identity refused');
select pg_temp.throws($q$update public.property_points_of_interest set name='Bypass'where id='ee600000-0000-4000-8000-000000000010'$q$,'adopted raw mutation blocked');
select pg_temp.throws($q$delete from public.neighborhood_versions where id='ee600000-0000-4000-8000-000000000010'$q$,'version evidence immutable');
select pg_temp.throws($q$update public.neighborhood_decisions set kind='approved'where id='ee600000-0000-4000-8000-000000000010'$q$,'decision evidence immutable');
select pg_temp.check_it(not has_table_privilege('authenticated','public.property_points_of_interest','SELECT')and not has_function_privilege('authenticated','public.decide_neighborhood_review(uuid,uuid,uuid,jsonb)','EXECUTE'),'raw clients cannot bypass tenant boundary');
update public.profiles set role='viewer'where id='11111111-1111-1111-1111-111111111111';
select pg_temp.check_it(pg_temp.read_source()->>'canManage'='false'and pg_temp.decide('ee600000-0000-4000-8000-000000000025',pg_temp.save_input())->>'state'='forbidden','viewer read only');
update public.profiles set role='admin'where id='11111111-1111-1111-1111-111111111111';
create function pg_temp.fail_activity()returns trigger language plpgsql as $$begin if new.property_id='ee600000-0000-4000-8000-000000000001'then raise exception 'Fixture action failure';end if;return new;end$$;
create trigger neighborhood_fixture_activity before insert on public.shared_action_events for each row execute function pg_temp.fail_activity();
select pg_temp.throws($q$select pg_temp.decide('ee600000-0000-4000-8000-000000000026',pg_temp.save_input())$q$,'activity failure rolls back decision');
drop trigger neighborhood_fixture_activity on public.shared_action_events;
select pg_temp.check_it(not exists(select 1 from public.neighborhood_workspaces where id='ee600000-0000-4000-8000-000000000026'),'no partial source after action failure');
insert into public.property_points_of_interest(id,property_id,org_id,name,category,address,source_url,captured_at,confidence,approval_status)values('ee600000-0000-4000-8000-000000000030','ee600000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','Earlier library','library','{"legacy":"retained"}','https://example.invalid/library','2026-01-01',1,'approved');
select pg_temp.check_it(pg_temp.read_source('{"kind":"point","pointId":"ee600000-0000-4000-8000-000000000030"}')->'source'->'workspace'='null','legacy remains honestly unrecorded');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000031',pg_temp.save_input('ee600000-0000-4000-8000-000000000030',pg_temp.draft()))->>'state'='saved','legacy adoption saves private version');
select pg_temp.check_it((select before_state->'point'->'address'='{"legacy":"retained"}'from public.neighborhood_decisions where id='ee600000-0000-4000-8000-000000000031'),'adoption preserves complete legacy before row');
select pg_temp.check_it(pg_temp.decide('ee600000-0000-4000-8000-000000000032',pg_temp.review_input('ee600000-0000-4000-8000-000000000030','archive'))->>'state'='saved','archiving legacy approval recorded');
select pg_temp.check_it(jsonb_array_length(public.neighborhood_approved_rows('ee600000-0000-4000-8000-000000000001'))=0,'archiving legacy approval removes source');
-- Full native inventory and version/history pages exceed the REST default limit.
insert into public.property_points_of_interest(id,property_id,org_id,name,category,approval_status)select md5('neighborhood-native-page:'||n)::uuid,'ee600000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','Earlier fixture place '||n,'fixture','pending'from generate_series(1,1005)n;
select pg_temp.check_it(pg_temp.read_source()->>'total'='1007'and jsonb_array_length(pg_temp.read_source()->'items')=20,'inventory includes every native row');
select pg_temp.check_it(jsonb_array_length(pg_temp.read_source('{"offset":1000}')->'items')=7,'inventory final page beyond default limit');
insert into st values('pageHash',pg_temp.read_source()->'pageHash');
update public.property_points_of_interest set name='Changed earlier fixture'where id=md5('neighborhood-native-page:1')::uuid;
select pg_temp.check_it(pg_temp.read_source(jsonb_build_object('offset',20,'expectedHash',(select v from st where k='pageHash')))->>'state'='history_changed','complete source hash fences paging');
insert into public.neighborhood_versions(id,point_id,property_id,org_id,actor_id,draft)select md5('neighborhood-version-page:'||n)::uuid,'ee600000-0000-4000-8000-000000000010','ee600000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111',pg_temp.draft()from generate_series(1,1005)n;
select pg_temp.check_it(pg_temp.read_source('{"kind":"versions","pointId":"ee600000-0000-4000-8000-000000000010","offset":1000}')->>'total'='1008','complete versions exceed 1000');
insert into public.neighborhood_decisions(id,point_id,property_id,org_id,actor_id,kind,input,input_hash,before_state,after_state,result)select md5('neighborhood-history-page:'||n)::uuid,'ee600000-0000-4000-8000-000000000010','ee600000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111','saved','{"reason":"Synthetic paging fixture"}',repeat('a',64),'{}','{}','{}'from generate_series(1,1005)n;
select pg_temp.check_it((pg_temp.read_source('{"kind":"history","offset":1000}')->>'total')::int>1005 and jsonb_array_length(pg_temp.read_source('{"kind":"history","offset":1000}')->'items')>5,'complete history exceeds 1000');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where property_id='ee600000-0000-4000-8000-000000000001'and(training_eligible or request::text like'%Station garden%')),'shared activity private and training excluded');
update public.property_points_of_interest set approval_status='approved'where property_id='ee600000-0000-4000-8000-000000000001'and id not in('ee600000-0000-4000-8000-000000000010','ee600000-0000-4000-8000-000000000030');
select pg_temp.check_it(jsonb_array_length(public.read_neighborhood_publication_source('ee600000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222')->'items')=1005,'publication reads complete approved rows beyond REST cap');
insert into public.organizations(id,name)values('ee600000-0000-4000-8000-000000000090','Neighborhood transfer SQL fixture');
update public.profiles set org_id='ee600000-0000-4000-8000-000000000090'where id='11111111-1111-1111-1111-111111111111';
select pg_temp.check_it(pg_temp.read_source()->>'state'='forbidden'and pg_temp.decide('ee600000-0000-4000-8000-000000000091',pg_temp.save_input())->>'state'='forbidden','transferred member cannot read or write old sources');
SET LOCAL session_replication_role=replica;
update public.properties set org_id='ee600000-0000-4000-8000-000000000090'where id='ee600000-0000-4000-8000-000000000001';
SET LOCAL session_replication_role=origin;
select pg_temp.check_it(pg_temp.read_source()->>'state'='scope_changed'and pg_temp.decide('ee600000-0000-4000-8000-000000000092',pg_temp.save_input())->>'state'='scope_changed','property transfer does not rebind prior private history');
select pg_temp.check_it(public.read_neighborhood_publication_source('ee600000-0000-4000-8000-000000000001','ee600000-0000-4000-8000-000000000090')->>'state'='scope_changed','transferred publication sources held');
select pg_temp.check_it(public.valid_neighborhood_draft(pg_temp.draft()||'{"sourceUrl":"https://www.google.com/maps/@0,0,10z"}'),'map source paths may contain at signs without credentials');
select n as passed_assertions from assertion_count;
ROLLBACK;
